class RoundRobin {
  constructor(lists) {
    this.lists = lists
    this.queue = []
    this.head = 0
    for (let i = 0; i < lists.length; i++) {
      if (lists[i].length > 0) this.queue.push([i, 0])
    }
  }

  hasNext() {
    return this.head < this.queue.length
  }

  next() {
    const [i, pos] = this.queue[this.head++]
    if (pos + 1 < this.lists[i].length) this.queue.push([i, pos + 1])
    return this.lists[i][pos]
  }
}

function runRoundRobin(lists, ops) {
  const it = new RoundRobin(lists)
  return ops.map(op => (op === 'next' ? it.next() : it.hasNext()))
}

