from collections import deque


class RoundRobin:
    def __init__(self, lists):
        self.lists = lists
        self.queue = deque((i, 0) for i, items in enumerate(lists) if items)

    def has_next(self):
        return len(self.queue) > 0

    def next(self):
        i, pos = self.queue.popleft()
        if pos + 1 < len(self.lists[i]):
            self.queue.append((i, pos + 1))
        return self.lists[i][pos]


def run_round_robin(lists, ops):
    it = RoundRobin(lists)
    return [it.next() if op == "next" else it.has_next() for op in ops]
